-- Batch 05: independently cross-checked public building sources. Two current evidence rows per field, one audit and one evidence group.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v5';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; sub_batch int:=5; expected_before int:=81; expected_added int:=19;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v5_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($ext$[{"id":"9d7135cf-6ac2-43f1-84d1-de62d8879667","f":"name_en","type":"text","value":"Hyundai Motor Tower","unit":"name","sources":[{"url":"https://www.hines.com/properties/hyundai-motor-tower-beijing","name":"Hines项目页","tier":"primary"},{"url":"https://talent.hyundai.com/eng/location/global.hc?continent=asia","name":"现代汽车企业官网","tier":"primary"}],"note":"同一霄云路38号项目英文名称。"},{"id":"9d7135cf-6ac2-43f1-84d1-de62d8879667","f":"parking_above","type":"integer","value":23,"unit":"count","sources":[{"url":"https://www.xiandaiqichedasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://wisoffice.cn/building/%E5%8C%97%E4%BA%AC-%E7%8E%B0%E4%BB%A3%E6%B1%BD%E8%BD%A6%E5%A4%A7%E5%8E%A6/","name":"Wisoffice楼宇资料","tier":"secondary"}],"note":"两份项目参数的地上地下停车数量一致；合计423。"},{"id":"9d7135cf-6ac2-43f1-84d1-de62d8879667","f":"parking_underground","type":"integer","value":400,"unit":"count","sources":[{"url":"https://www.xiandaiqichedasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://wisoffice.cn/building/%E5%8C%97%E4%BA%AC-%E7%8E%B0%E4%BB%A3%E6%B1%BD%E8%BD%A6%E5%A4%A7%E5%8E%A6/","name":"Wisoffice楼宇资料","tier":"secondary"}],"note":"两份项目参数的地上地下停车数量一致；合计423。"},{"id":"9d7135cf-6ac2-43f1-84d1-de62d8879667","f":"parking_total","type":"integer","value":423,"unit":"count","sources":[{"url":"https://www.xiandaiqichedasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://wisoffice.cn/building/%E5%8C%97%E4%BA%AC-%E7%8E%B0%E4%BB%A3%E6%B1%BD%E8%BD%A6%E5%A4%A7%E5%8E%A6/","name":"Wisoffice楼宇资料","tier":"secondary"}],"note":"两份项目参数的地上地下停车数量一致；合计423。"},{"id":"9d7135cf-6ac2-43f1-84d1-de62d8879667","f":"floors_below","type":"integer","value":3,"unit":"floor","sources":[{"url":"https://www.xiandaiqichedasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.xzlsd.com/information/detail/43588.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"地下楼层一致；地上楼层口径不统一，未填。"},{"id":"9d7135cf-6ac2-43f1-84d1-de62d8879667","f":"telecom_provider","type":"text","value":"电信、联通、移动等","unit":"configuration","sources":[{"url":"https://www.xiandaiqichedasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.xzlsd.com/m/minfo/detail/43589.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"取共同支持的运营商名称，非完整现时可用运营商清单。"},{"id":"8dbf6b03-52bf-4d39-b3c3-2fd1558af2dc","f":"standard_floor_area","type":"numeric","value":1833,"unit":"m2","sources":[{"url":"https://www.bjhuijiadasha.cn/index.html","name":"汇佳大厦项目资料","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/312.html","name":"明德房产网","tier":"secondary"}],"note":"东三环北路6号同一项目，标准层面积与货梯数量一致。其他存在口径差异的参数未填。"},{"id":"8dbf6b03-52bf-4d39-b3c3-2fd1558af2dc","f":"elevator_freight","type":"integer","value":1,"unit":"count","sources":[{"url":"https://www.bjhuijiadasha.cn/index.html","name":"汇佳大厦项目资料","tier":"secondary"},{"url":"https://www.mingdefang.cn/beijingshi/zufang/312.html","name":"明德房产网","tier":"secondary"}],"note":"东三环北路6号同一项目，标准层面积与货梯数量一致。其他存在口径差异的参数未填。"},{"id":"11dc48b4-7dfe-4e31-a38e-a99fed28c594","f":"hvac_pm25_purification","type":"boolean","value":true,"unit":"boolean","sources":[{"url":"https://www.donghuzx.cn/index.html","name":"东湖国际中心项目资料","tier":"secondary"},{"url":"https://www.xzlsd.com/information/detail/40959.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"历史公开资料相符；认证未声明当前有效；地铁只记站名，不记录距离。"},{"id":"11dc48b4-7dfe-4e31-a38e-a99fed28c594","f":"green_building_standard","type":"text","value":"北京绿色建筑二星（历史资料）","unit":"certification","sources":[{"url":"https://www.donghuzx.cn/index.html","name":"东湖国际中心项目资料","tier":"secondary"},{"url":"https://www.xzlsd.com/information/detail/40959.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"历史公开资料相符；认证未声明当前有效；地铁只记站名，不记录距离。"},{"id":"11dc48b4-7dfe-4e31-a38e-a99fed28c594","f":"metro_access","type":"text","value":"地铁14号线东湖渠站","unit":"nearby_station","sources":[{"url":"https://www.donghuzx.cn/index.html","name":"东湖国际中心项目资料","tier":"secondary"},{"url":"https://www.xzlsd.com/information/detail/40959.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"历史公开资料相符；认证未声明当前有效；地铁只记站名，不记录距离。"},{"id":"58cf5abc-1b92-4990-8619-cf6fc3448092","f":"metro_access","type":"text","value":"地铁14号线阜通站","unit":"nearby_station","sources":[{"url":"https://www.shoukaiguangchang.cn/","name":"首开广场项目资料","tier":"secondary"},{"url":"https://www.jb-sw.cn/","name":"金保商务楼宇资料","tier":"secondary"}],"note":"阜荣街10号项目周边站点；不填步行距离。"},{"id":"a694de38-87cc-4892-b492-25541113fa38","f":"name_en","type":"text","value":"China Life Financial Center","unit":"name","sources":[{"url":"https://www.deloitte.com/cn/en/offices/beijing.html","name":"德勤办公地址","tier":"primary"},{"url":"https://projcf.com/find-local-office/","name":"企业办公地址","tier":"primary"}],"note":"同一针织路23号英文楼名。"},{"id":"a7a67622-df55-4062-b15c-39187075b0cb","f":"name_en","type":"text","value":"POSCO Center","unit":"name","sources":[{"url":"https://poscoenc.com/en/about_us/network.aspx","name":"POSCO企业办公地址","tier":"primary"},{"url":"https://www.sec.gov/Archives/edgar/data/1509646/000119312526188853/feng-20251231.htm","name":"SEC企业申报文件","tier":"primary"}],"note":"同一宏泰东街浦项中心楼名，非单塔独立命名。"},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"name_en","type":"text","value":"East Gate Plaza","unit":"name","sources":[{"url":"https://wri.org.cn/en/about/contact","name":"世界资源研究所办公地址","tier":"primary"},{"url":"https://webresource.ctrip.com/code/engpurehtml/footer/contact.html","name":"携程办公地址","tier":"primary"}],"note":"东中街9号，英文项目名称一致。"},{"id":"84ffb230-ae43-41ee-a15d-bd03e63c0ba1","f":"parking_total","type":"integer","value":585,"unit":"count","sources":[{"url":"https://www.dongxuguoji.cn/","name":"东旭国际中心项目资料","tier":"secondary"},{"url":"https://www.bjttlj.cn/detail-43.html","name":"北京智慧商务选址","tier":"secondary"}],"note":"四栋项目合计585；公开资料地上地下划分有矛盾，因此仅填总数。"},{"id":"84ffb230-ae43-41ee-a15d-bd03e63c0ba1","f":"metro_access","type":"text","value":"地铁9号线丰台科技园站","unit":"nearby_station","sources":[{"url":"https://www.bjttlj.cn/detail-43.html","name":"北京智慧商务选址","tier":"secondary"},{"url":"https://www.fang.com/xiaoqu/bj-1010829035/","name":"房天下楼盘资料","tier":"secondary"}],"note":"同一园区，记录共同支持站名，不记录距离或排除其他站点。"},{"id":"d6dbe652-fb9b-4eef-85b1-330620e41ba5","f":"efficiency_rate","type":"numeric","value":70,"unit":"percent","sources":[{"url":"https://www.bjjingfang.com/index/lease/detail?id=10961","name":"北京京房楼宇资料","tier":"secondary"},{"url":"https://www.sbzszx.com/productinfo/56579.html","name":"商办招商楼宇资料","tier":"secondary"}],"note":"同一远洋锐中心写字楼，公开招商使用率约70%，非现场测量。"},{"id":"80dec004-1daf-43b3-a545-071a3fc3b023","f":"name_en","type":"text","value":"Ping An International Financial Center","unit":"name","sources":[{"url":"https://www.reedexport.cn/zh-cn/contact-us.html","name":"励展博览集团办公地址","tier":"primary"},{"url":"https://en.thcapital.com.cn/contactus/","name":"华控基金办公地址","tier":"primary"}],"note":"新源南路1-3号A、B座办公地址共同确认项目英文名称。"}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text)) SELECT b.id bid,b.name,d.id target_id,v.f field_name,v.value new_value,v.type value_type,v.unit,v.sources,v.note FROM specs v JOIN building_brochure_data d ON d.id=v.id JOIN buildings b ON b.id=d.building_id WHERE b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.project_type='stock' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data q WHERE q.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND (SELECT count(distinct substring(s->>'url' from 'https?://([^/]+)')) FROM jsonb_array_elements(v.sources) s)>=2 AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=b.id AND p.target_table='building_brochure_data' AND p.field_name=v.f) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=d.id::text AND (a.details->>'field_name'=v.f OR a.new_values ? v.f)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_url,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  SELECT r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'internet',e->>'tier',e->>'name',e->>'url',now_ts,now_ts,'cross_verified',ev,'batch_ref=ai_building_field_backfill_20261125_v5_100; unit='||r.unit||'; '||r.note||'; AI-assisted',true FROM jsonb_array_elements(r.sources) e;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>jsonb_array_length(r.sources) OR changed<2 THEN RAISE EXCEPTION 'source count mismatch'; END IF;
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v5_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_kind','external_cross_verified','source_urls',r.sources,'unit',r.unit,'verification_status','cross_verified','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value)<>jsonb_array_length(r.sources) OR NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.event_id='ai_field_fill:'||ev::text AND a.new_values->r.field_name=read_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected %, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
COMMIT;